var n=[{title:`Nombreuses causes, nombreuses réponses`,text:`Les gens ressentent une gêne dans le dos pour des raisons différentes, et même des symptômes semblables peuvent avoir des causes différentes. Certaines personnes tolèrent bien la flexion, tandis que d’autres préfèrent un tronc plus neutre. Le meilleur exercice pour vous dépend de vos symptômes, de votre capacité, de votre expérience et des conseils éventuels de votre médecin.`},{title:`Gérer les sollicitations`,text:`Entraînez-vous à gainer sans retenir trop longtemps votre souffle, apprenez une charnière contrôlée avec un poids léger et essayez des exercices avec appui ou au sol quand ils vous conviennent. Un bird dog doux ou un dead bug travaille le contrôle du tronc sans poids lourds. Aucune posture unique ne garantit la sécurité, et garder une « colonne neutre » ne veut pas dire bloquer tous les mouvements normaux de la colonne.`},{title:`Progresser avec le temps`,text:`Si c’est confortable, rendez l’entraînement lentement plus difficile en ajoutant des répétitions, de l’amplitude ou de la charge. Notez ce que vous ressentez dans le dos pendant et après les séances. Si les symptômes s’aggravent, simplifiez. En cas de douleur persistante, demandez l’avis d’un professionnel ; les choix d’exercices d’une application ne peuvent pas s’y substituer.`},{title:`Signes urgents`,text:`De nouveaux changements au niveau de la vessie ou des intestins, un engourdissement autour de l’aine, une faiblesse sévère ou croissante dans les jambes, ou un mal de dos après un traumatisme important nécessitent une évaluation médicale urgente.`},{title:`Avec TrainUp`,text:`Ajoutez le bas de votre dos comme limitation dans Profil, avec une note, pour que le programme choisisse des exercices adaptés. Après chaque séance, vous pouvez ajouter des notes et signaler une douleur avec la zone du corps et l’exercice. Si un exercice provoque une douleur, « J’ai mal » y met fin et le garde hors de vos programmes jusqu’à ce que vous le réactiviez depuis Profil. TrainUp ne diagnostique pas la cause d’un mal de dos.`}];var t=[{label:`NHS : mal de dos et signes d’alerte urgents`,url:`https://www.nhs.uk/conditions/back-pain/`},{label:`Prise de position 2026 de l’ACSM`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var u={sections:n,sources:t};export{u as default,n as sections,t as sources};